/* Private planning prototype. Technical product specifications still require approval. */
'use strict';
const S=window.GestorSchedule;
const $=q=>document.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h3m3 0h2m-8 3h3"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',line:'<rect x="3" y="8" width="18" height="8" rx="2"/><path d="M6 8V4m6 4V4m6 4V4M6 16v4m6-4v4m6-4v4M7 12h10"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8m-8 4h6"/>',book:'<path d="M12 5c-3-2-7-2-10-1v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1v16"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6"/>',alert:'<path d="m12 3 10 18H2zM12 9v4m0 4v.01"/>',pin:'<path d="m9 3 6 0-1 6 4 4v2H6v-2l4-4zM12 15v7"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',moon:'<path d="M20 14a9 9 0 0 1-10-11 9 9 0 1 0 10 11"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M9 5v14M15 5v14"/>',down:'<path d="M12 4v16m-6-6 6 6 6-6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
const avatar=name=>`<span class="avatar">${esc(name.slice(0,2).toUpperCase())}</span>`;
const linkButton=(href,text,primary=false,ico='arrow')=>`<a href="#${href}" class="button ${primary?'primary':''}">${esc(text)}${icon(ico)}</a>`;
const defaultProducts=[];
const pages=[['overview','Visão geral','grid'],['schedule','Montar escala','calendar'],['employees','Funcionários','users'],['fp','FPs','file'],['history','Histórico','clock'],['settings','Configurações','shield']];
const initialSectors=['Sala de máquinas','Linha de Bolsas','Subconjunto','Embalagem final','Outros'];
const sectors=()=>Array.isArray(config.sectors)?config.sectors:initialSectors;
let config=S.defaults(), employees=[], result=null, viewIndex=0, theme='dark', query='',fpFocus='',storageMode='loading',lastSaved='',saveTimer=null,saveQueue=Promise.resolve(),pendingOperation=null;
const STORAGE='gestor-subconjunto-v4';
try{localStorage.removeItem('gestor-subconjunto-v2');theme=localStorage.getItem('gestor-theme')==='light'?'light':'dark';}catch{}
const payload=()=>({config,employees,generated:!!result,...(pendingOperation?{operation:pendingOperation}:{})});
function storageStatus(message){const el=$('#storageStatus');if(el)el.textContent=message;}
async function persist(){
 const latest=JSON.stringify(payload());if(latest===lastSaved)return;
 storageStatus('Salvando no banco SQL…');
 const response=await fetch('/api/state.js',{method:'PUT',headers:{'Content-Type':'application/json'},body:latest});
 if(!response.ok)throw new Error((await response.json().catch(()=>({}))).error||'Falha ao salvar.');
 pendingOperation=null;lastSaved=JSON.stringify(payload());storageStatus('Dados salvos no banco SQL.');
}
function commit(){clearTimeout(saveTimer);saveQueue=saveQueue.catch(()=>{}).then(persist);return saveQueue;}
function save(){
 if(storageMode==='loading')return;
 try{localStorage.setItem('gestor-theme',theme);}catch{}
 const data=JSON.stringify(payload());if(data===lastSaved)return;
 if(storageMode==='local'){
  try{localStorage.setItem(STORAGE,JSON.stringify({version:4,...payload()}));lastSaved=data;storageStatus('Rascunho local · banco SQL aguardando configuração.');}
  catch{storageStatus('Salvamento local indisponível.');}
  return;
 }
 clearTimeout(saveTimer);saveTimer=setTimeout(()=>{commit().catch(error=>{storageStatus('Falha ao salvar no banco SQL.');notify(error.message);});},450);
}
async function loadState(){
 try{
  const response=await fetch('/api/state.js',{cache:'no-store'});
  if(!response.ok)throw new Error('Banco não configurado');
  const saved=await response.json();config={...S.defaults(),...saved.config};employees=saved.employees||[];
  const upgraded=upgradeLegacyFpIds();
  if(saved.generated&&employees.length&&catalog().length)result=buildResult();
  storageMode='sql';lastSaved=upgraded?'':JSON.stringify(payload());storageStatus('Dados salvos no banco SQL.');
 }catch{
  try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(saved?.version===4&&Array.isArray(saved.employees)){
   config={...config,...saved.config};employees=saved.employees;if(saved.generated&&employees.length&&catalog().length)result=buildResult();
  }}catch{}
  storageMode='local';lastSaved=JSON.stringify(payload());storageStatus('Rascunho local · banco SQL aguardando configuração.');
 }
 render();
}
function invalidate(){result=null;viewIndex=0;delete config.confirmedId;save();}
function upgradeLegacyFpIds(){
 const mapping=new Map();for(const p of config.fps||[])if(!/^[0-9a-f-]{36}$/i.test(p.id)){const replacement=crypto.randomUUID();mapping.set(p.id,replacement);p.id=replacement;}
 if(!mapping.size)return false;
 config.product=mapping.get(config.product)||config.product;
 for(const h of config.history||[]){h.fpId=mapping.get(h.fpId)||h.fpId;if(h.snapshot?.config?.product)h.snapshot.config.product=mapping.get(h.snapshot.config.product)||h.snapshot.config.product;}
 return true;
}
const catalog=()=>Array.isArray(config.fps)?config.fps:defaultProducts;
const activeCatalog=()=>catalog().filter(p=>p.status!=='Arquivada');
const selected=()=>employees.filter(p=>p.active&&p.present&&(p.role||'Operador')==='Operador');
const assistants=()=>employees.filter(p=>p.active&&p.present&&p.role==='Assistente');
const organizers=()=>assistants().filter(p=>(config.organizerIds||[]).includes(p.id));
const extras=()=>Array.isArray(config.extraPosts)?config.extraPosts:[];
const extraSlots=()=>S.extraSlots(config);
const product=()=>activeCatalog().find(p=>p.id===config.product)||activeCatalog()[0]||{id:'',name:'Nenhum produto cadastrado',market:'Nacional',variation:'',fp:'FP pendente',revision:'—'};
function buildResult(){
 const chosen=product();const output=S.generate({...config,fpStations:fpStations(chosen)},employees);
 if(output.errors.length)return output;
 output.extraPosts=structuredClone(extraSlots());
 output.organizers=organizers().map(p=>({id:p.id,name:p.name}));
 const blocks=output.rows.filter(r=>r.kind==='work');
 for(const post of output.extraPosts)if(!post.employeeId&&blocks.length)output.gaps.push({station:post.key,start:blocks[0].start,end:blocks.at(-1).end});
 output.complete=!output.gaps.length&&!output.warnings.length;
 return output;
}
function reconcileAssignments(){
 const live=new Map(employees.filter(p=>p.present&&p.active).map(p=>[p.id,p]));
 config.organizerIds=(config.organizerIds||[]).filter(id=>live.get(id)?.role==='Assistente');
 for(const post of extras()){post.employeeIds=(post.employeeIds||[post.employeeId||'']).map(id=>{const p=live.get(id);return p&&(p.role||'Operador')==='Operador'&&!p.noGlue&&!p.fixed?id:'';});post.employeeId=post.employeeIds[0]||'';}
}
const nameOf=(id,source=employees)=>source.find(p=>p.id===id)?.name||'Pendente';
function hintOf(p){return p.noGlue?'Sem cola · somente clampe':p.fixed?`Fixo · ${S.stations.find(s=>s.id===p.fixed)?.name}`:'Participa do rodízio';}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function heading(kicker,title,subtitle,action=''){return `<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div>${action}</div>`;}
function alertBox(text,tone=''){return `<div class="alert ${tone}">${icon(tone==='success'?'check':tone==='info'?'file':'alert')}<div>${text}</div></div>`;}
function metric(label,value,unit,foot,ico){return `<article class="metric"><span class="metric-icon">${icon(ico)}</span><div><span class="metric-label">${label}</span><strong>${value}<small>${unit}</small></strong><span class="metric-foot">${foot}</span></div></article>`;}
function statusText(){return !result?'Pendente':result.errors.length?'Em montagem':result.complete?(config.confirmedId?'Pronta':'Em montagem'):'Incompleta';}
function displayRow(){if(result?.rows.length)return result.rows[Math.min(viewIndex,result.rows.length-1)];return null;}
function overview(){
 const now=new Date(),p=product(),row=displayRow(),positions=result?.positions||S.slots({fpStations:fpStations(p)}),filled=row?.kind==='work'?row.assign.filter(Boolean).length:0,total=positions.length,status=statusText();
 const personAt=(id)=>result?.employees.find(x=>x.id===id)?.name||'Funcionário não definido';
 $('#app').innerHTML=heading('CENTRAL OPERACIONAL','Gestor de Subconjunto','Planejamento da linha de produção · Versão Piloto',linkButton('schedule','Montar escala',true,'plus'))+`<div class="pilot-today"><div><span class="eyebrow">PRODUÇÃO DE HOJE</span><h2 id="pilotClock">${now.toLocaleDateString('pt-BR')} · ${now.toLocaleTimeString('pt-BR')}</h2><p>Turno ${esc(config.shiftName||'não selecionado')} · ${esc(p.fp||'Nenhuma FP cadastrada')} · ${esc(p.product||p.name||'Produto não definido')}</p><p><strong>Assistente responsável:</strong> ${organizers().length?organizers().map(x=>esc(x.name)).join(', '):'Não selecionada'}</p></div>${badge(status,status==='Pronta'?'green':'amber')}</div>
 <div class="metrics">${metric('Operadores ativos',selected().length,'','Disponíveis para atribuição','users')}${metric('Postos ocupados',filled,`/ ${total}`,row?.kind==='break'?'Equipe em intervalo':'No quadro da escala','line')}${metric('Disponíveis',Math.max(0,selected().length-filled-(result?.extraPosts||[]).filter(x=>x.employeeId).length),'','Fora dos postos neste horário','users')}${metric('Situação',status,'','Da escala atual','shield')}</div>
 ${!catalog().length?`<div class="card empty-state"><h2>Nenhuma FP cadastrada</h2><p>Cadastre a primeira FP antes de montar a escala.</p>${linkButton('fp','Adicionar FP',true,'plus')}</div>`:!employees.length?`<div class="card empty-state"><h2>Nenhum funcionário cadastrado</h2><p>Cadastre os colaboradores disponíveis para começar.</p>${linkButton('employees','Adicionar funcionário',true,'plus')}</div>`:!result?`<div class="card empty-state"><h2>Nenhuma escala criada para hoje</h2><p>Selecione a FP e o turno para começar.</p>${linkButton('schedule','Montar primeira escala',true,'plus')}</div>`:''}
 <section class="card pilot-line"><div class="card-head"><div><h2>Linha de produção</h2><p>${esc(p.fp||'FP pendente')} · ${esc(p.name||'Produto não definido')}</p></div>${badge(status,status==='Pronta'?'green':'amber')}</div><div class="pilot-line-grid">${positions.map((s,j)=>{const id=row?.assign[j],name=id?personAt(id):'Funcionário não definido';return `<article class="pilot-station ${id?'is-covered':'is-pending'}"><span class="station-index">${esc(s.id)}</span><div><strong>${esc(s.name)}${s.slot>1?' · '+s.slot+'ª posição':''}</strong><span class="person-name" title="${esc(name)}">${esc(name)}</span><small>${id?'✓ Escalado':'⚠ Pendente'}</small></div></article>`;}).join('')}</div>${result?.rows.length?`<div class="view-slider"><label for="timeSlider">Horário do quadro</label><input type="range" id="timeSlider" min="0" max="${result.rows.length-1}" value="${viewIndex}"><output id="timeOutput">${S.clock(row.start)} — ${S.clock(row.end)}</output></div>`:''}</section>`;
 const slider=$('#timeSlider');if(slider)slider.addEventListener('input',e=>{viewIndex=Number(e.target.value);overview();});
}
function dateLabel(value){const d=new Date(value+'T12:00:00');return Number.isNaN(d.getTime())?'Data não definida':d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});}
function options(values,selectedValue){return values.map(v=>`<option value="${esc(v.value)}" ${v.value===selectedValue?'selected':''}>${esc(v.label)}</option>`).join('');}
function schedule(){
 const p=product(),reserved=new Set(extraSlots().map(x=>x.employeeId).filter(Boolean)),available=selected().filter(person=>!reserved.has(person.id)),positions=S.slots({fpStations:fpStations(p)});
 const stationSelect=s=>{const eligible=available.filter(person=>S.eligible(person,s,config.date)),assigned=config.manualAssignments?.[s.key]||'',locked=config.locks?.[s.key]||'';return `<article class="station-select ${eligible.length?'':'station-empty'}"><div><span class="station-index">${s.id}</span><span><b>${esc(s.name)}${s.slot>1?' · '+s.slot+'ª posição':''}</b><small>${s.limit?`Troca a cada ${s.limit} min`:'Rodízio geral'} · ${eligible.length} habilitados</small></span></div><label class="field"><span class="sr-only">Operador inicial no posto ${s.id}, posição ${s.slot}</span><select name="station-${s.key}" aria-label="Operador inicial no posto ${s.id}, posição ${s.slot}"><option value="">Distribuir automaticamente</option>${eligible.map(person=>`<option value="${esc(person.id)}" ${assigned===person.id?'selected':''}>${esc(person.name)}${person.fixed===s.id?' · Fixo':''}</option>`).join('')}</select></label><label class="check-field"><input type="checkbox" name="lock-${s.key}" ${locked?'checked':''} ${assigned?'':'disabled'}>Fixar neste posto</label></article>`;};
 const extraRows=extraSlots().map(x=>`<article class="station-select extra-select"><div><span class="station-index">${esc(x.id)}</span><span><b>${esc(x.name)}${x.slot>1?' · '+x.slot+'ª posição':''}</b><small>${esc(x.notes||'Alocação manual · turno inteiro')}</small></span></div><label class="field"><span class="sr-only">Operador do posto adicional ${esc(x.id)}, posição ${x.slot}</span><select name="extra-${esc(x.key)}" aria-label="Operador do posto adicional ${esc(x.id)}, posição ${x.slot}">${options([{value:'',label:'Pendente · escolher operador'},...selected().filter(person=>!person.noGlue&&!person.fixed&&(!reserved.has(person.id)||person.id===x.employeeId)).map(person=>({value:person.id,label:person.name}))],x.employeeId||'')}</select></label>${x.slot===1?`<button type="button" class="button small" data-remove-extra="${esc(x.id)}" aria-label="Remover posto ${esc(x.id)}">Remover</button>`:''}</article>`).join('');
 $('#app').innerHTML=heading('PLANEJAMENTO DO TURNO','Montagem de escala','Escolha o tipo de subconjunto e distribua a equipe pelos postos.',linkButton('overview','Visão geral',false,'grid'))+
 `<form id="scheduleForm" class="card schedule-form"><section class="form-section"><div class="form-section-heading"><span class="step">1</span><h3>Tipo de subconjunto</h3><span class="helper">Organizado por destino e variação</span></div><div class="form-grid three"><label class="field">Data<input type="date" name="date" value="${esc(config.date)}" required></label><label class="field">Turno<select name="shiftName">${options((config.shifts||[]).map(x=>({value:x.name,label:x.name})),config.shiftName)}</select></label><label class="field">Destino<select name="market">${options(['Nacional','Internacional'].map(x=>({value:x,label:x})),p.market)}</select></label><label class="field">Variação<select name="product">${options(activeCatalog().filter(x=>x.market===p.market).map(x=>({value:x.id,label:x.name})),p.id)}</select></label></div><div class="product-summary"><span>${badge(p.market,'green')}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.fp)} · revisão ${esc(p.revision)}</small></span><a href="#fp" class="text-button">Ver FPs ${icon('arrow')}</a></div>${!catalog().length?alertBox('Cadastre uma FP na página FP e produtos antes de gerar a escala.','info'):''}</section>
 <section class="form-section"><div class="form-section-heading"><span class="step">2</span><h3>Assistentes responsáveis</h3><span class="helper">${assistants().length} disponíveis</span></div><p class="helper form-copy">Selecione quem organiza a linha neste turno. Assistentes não ocupam os postos de operador.</p><div class="organizer-list">${assistants().map(person=>`<label class="check-field"><input type="checkbox" name="organizer" value="${esc(person.id)}" ${(config.organizerIds||[]).includes(person.id)?'checked':''}>${esc(person.name)} · ${esc(person.sector)}</label>`).join('')||'<p class="helper">Nenhum assistente ativo. Cadastre ou ative uma pessoa na categoria Assistente.</p>'}</div></section>
 <section class="form-section"><div class="form-section-heading"><span class="step">3</span><h3>Postos da linha</h3><span class="helper">${available.length} operadores disponíveis para o rodízio</span></div><p class="helper form-copy">Selecione quem começa em cada posto ou deixe em automático. O sistema mantém as restrições e mostra pendências quando faltar cobertura.</p><div class="station-selection">${positions.map(stationSelect).join('')}</div><div class="selection-toolbar"><a href="#employees" class="text-button">${icon('users')} Gerenciar disponibilidade dos funcionários</a></div></section>
 <section class="form-section"><div class="form-section-heading"><span class="step">4</span><h3>Outros postos</h3><span class="helper">${extras().length} adicionais</span></div><p class="helper form-copy">Cadastre postos de apoio para este turno e escolha um operador ativo para cada um. A alocação permanece durante o turno, exceto nos intervalos, e retira essa pessoa do rodízio 20–70.</p><div class="station-selection">${extraRows||'<p class="helper">Nenhum posto adicional neste turno.</p>'}</div><button type="button" class="button soft" data-action="add-extra">${icon('plus')} Adicionar outro posto</button></section>
 <details class="advanced-settings"><summary>Horários e rodízio da simulação</summary><div class="advanced-settings-body"><div class="form-grid three"><label class="field">Entrada<input type="time" name="start" value="${esc(config.start)}" required></label><label class="field">Saída<input type="time" name="end" value="${esc(config.end)}" required></label><label class="field">Rodízio geral<select name="rotation">${options([{value:'afterLunch',label:'Primeira troca após o almoço'},{value:'everyTwoHours',label:'A cada 2h trabalhadas desde a entrada'}],config.rotation)}</select></label></div><div class="break-settings"><label>Café<input type="time" name="coffee" value="${esc(config.coffee)}" aria-label="Início do café" required></label><label>Duração<input type="number" min="1" max="120" name="coffeeDuration" value="${esc(config.coffeeDuration)}" aria-label="Duração do café" required>min</label><label>Almoço<input type="time" name="lunch" value="${esc(config.lunch)}" aria-label="Início do almoço" required></label><label>Duração<input type="number" min="1" max="120" name="lunchDuration" value="${esc(config.lunchDuration)}" aria-label="Duração do almoço" required>min</label></div></div></details>
 <div class="generation-bar"><p><strong>Planejamento do turno.</strong><br>A disponibilidade vem da tela Funcionários.</p><button type="submit" class="button primary" id="generateButton" ${activeCatalog().length?'':'disabled'}>${icon('spark')} Gerar escala</button></div></form><div id="scheduleResult">${renderResult()}</div><div id="preckoffResult">${renderPreckoffPlan()}</div>`;
 $('#scheduleForm').addEventListener('change',e=>{const name=e.target.name;if(name==='market'){config.product=activeCatalog().find(item=>item.market===e.target.value)?.id||'';config.manualAssignments={};config.locks={};invalidate();schedule();return;}if(name==='product'){config.product=e.target.value;config.manualAssignments={};config.locks={};invalidate();schedule();return;}if(name==='shiftName'){const shift=(config.shifts||[]).find(x=>x.name===e.target.value);if(shift){config.shiftName=shift.name;config.start=shift.start;config.end=shift.end;invalidate();schedule();notify('Turno selecionado. Confira os intervalos em Horários e rodízio.');}return;}if(name==='organizer'){config.organizerIds=[...e.currentTarget.querySelectorAll('[name=organizer]:checked')].map(x=>x.value);invalidate();schedule();return;}if(name.startsWith('extra-')){const [id,slot]=name.slice(6).split('-'),post=extras().find(x=>x.id===id);if(post){post.employeeIds=post.employeeIds||[post.employeeId||''];post.employeeIds[Number(slot)-1]=e.target.value;post.employeeId=post.employeeIds[0]||'';const person=employees.find(x=>x.id===e.target.value);if(person)person.initial='';invalidate();schedule();}return;}if(name.startsWith('station-')){const key=name.slice(8);config.manualAssignments={...(config.manualAssignments||{}),[key]:e.target.value};if(config.locks?.[key]&&config.locks[key]!==e.target.value)delete config.locks[key];invalidate();schedule();return;}if(name.startsWith('lock-')){const key=name.slice(5),id=config.manualAssignments?.[key];config.locks={...(config.locks||{})};if(e.target.checked&&id){if(Object.values(config.locks).includes(id)){notify('Este operador já está fixado em outro posto.');schedule();return;}config.locks[key]=id;}else delete config.locks[key];invalidate();schedule();return;}if(Object.hasOwn(config,name)){config[name]=name.endsWith('Duration')?Number(e.target.value):e.target.value;invalidate();$('#scheduleResult').innerHTML=renderResult();$('#preckoffResult').innerHTML=renderPreckoffPlan();}});
 $('#scheduleForm').addEventListener('submit',e=>{e.preventDefault();if(!activeCatalog().some(x=>x.id===config.product)){notify('Cadastre e selecione uma FP antes de gerar a escala.');return;}const form=new FormData(e.currentTarget);for(const key of Object.keys(config))if(form.has(key))config[key]=key.endsWith('Duration')?Number(form.get(key)):form.get(key);result=buildResult();viewIndex=0;save();$('#scheduleResult').innerHTML=renderResult();$('#preckoffResult').innerHTML=renderPreckoffPlan();$('#scheduleResult').scrollIntoView({behavior:'smooth',block:'start'});notify(result.errors.length?'Revise a configuração antes de gerar a escala.':result.complete?'Escala gerada sem lacunas de cobertura.':'Escala gerada com pendências para revisão.');});
}
function renderPreckoffPlan(){
 if(!selected().length)return '';
 if(!fpStations(product()).some(s=>s.id==='40'))return '';
 if(fpStations(product()).find(s=>s.id==='40')?.requiredCount>1)return `<section class="result-section preckoff-plan">${alertBox('Esta FP exige mais de uma posição no Preckoff. Consulte a escala principal, que verifica todas as posições; a lista horária separada atende apenas uma posição.','info')}</section>`;
 const plan=S.generatePreckoff(config,employees);
 if(plan.errors.length)return `<section class="result-section preckoff-plan"><div class="result-heading"><div><h2>Escala exclusiva · Preckoff</h2><p class="helper">Gere por hora após corrigir os horários do turno.</p></div></div>${alertBox(plan.errors.map(esc).join('<br>'))}</section>`;
 const row=plan.entries.map(entry=>{const person=plan.employees.find(p=>p.id===entry.personId);const when=entry.fragments.map(f=>`${S.clock(f.start)} — ${S.clock(f.end)}`).join(' + ');return `<tr><td>${entry.slot}</td><td>${when}<small>${entry.minutes} min efetivos</small></td><td class="${person?'changed':'gap'}">${person?esc(person.name):'Pendente'}${person?.supportPreckoff?'<small>apoio de preckoff</small>':''}</td></tr>`;}).join('');
 return `<section class="result-section preckoff-plan"><div class="result-heading"><div><h2>Escala exclusiva · Preckoff</h2><div class="result-meta">${badge('Troca a cada 1h','green')}<span>${plan.entries.length} ciclos</span><span>Restritos excluídos</span></div></div><div class="actions"><button class="button small" data-action="preckoff-print">${icon('download')} Gerar PDF do preckoff</button></div></div>${plan.warnings.length?alertBox(plan.warnings.map(esc).join('<br>')):alertBox('Lista horária criada somente com pessoas elegíveis para o posto 40.','success')}<div class="card"><div class="table-scroll"><table class="schedule-table preckoff-table"><thead><tr><th>CICLO</th><th>HORÁRIO</th><th>POSTO 40 · PRECKOFF</th></tr></thead><tbody>${row}</tbody></table></div></div></section>`;
}
function renderResult(){
 if(!result)return `<div class="result-section">${alertBox(employees.length?'Há alterações ainda não aplicadas. Clique em <strong>Gerar escala</strong> para calcular uma nova distribuição.':'Cadastre funcionários, marque quem está Ativo na linha e depois gere a escala.','info')}</div>`;
 if(result.errors.length)return `<section class="result-section">${alertBox(result.errors.map(esc).join('<br>'))}</section>`;
 const extraPosts=result.extraPosts||[],organizerNames=(result.organizers||[]).map(p=>p.name);
 let previous=[];
 const rows=result.rows.map(row=>{
  if(row.kind==='break')return `<tr class="break-row"><td class="time-cell">${S.clock(row.start)} — ${S.clock(row.end)}</td><td colspan="${result.positions.length+extraPosts.length}">${row.label} · ${row.end-row.start} min · toda a equipe em intervalo</td></tr>`;
  const cells=row.assign.map((id,j)=>{const p=result.employees.find(x=>x.id===id);return `<td class="${!id?'gap':id!==previous[j]?'changed':''}">${id?esc(p?.name):'Pendente'}${p?.fixed?'<span class="fixed-mark"> · fixo</span>':''}${p?.noGlue?'<small>somente clampe</small>':''}</td>`;}).join('');previous=row.assign;
  const additional=extraPosts.map(post=>`<td class="${post.employeeId?'changed':'gap'}">${post.employeeId?esc(nameOf(post.employeeId,result.employees)):'Pendente'}<small>Alocação manual</small></td>`).join('');
  return `<tr><td class="time-cell">${S.clock(row.start)} — ${S.clock(row.end)}<small>${esc(row.label)} · ${row.end-row.start} min</small></td>${cells}${additional}</tr>`;
 }).join('');
 return `<section class="result-section"><div class="print-only"><h1>GESTOR DE SUBCONJUNTO</h1><p>Data: ${dateLabel(result.config.date)} · Turno: ${esc(result.config.shiftName)} · FP: ${esc(catalog().find(p=>p.id===result.config.product)?.fp)} · Produto: ${esc(product().product||product().name)}</p><p>Assistente responsável: ${organizerNames.map(esc).join(', ')||'Não selecionada'} · Situação: ${esc(statusText())}</p><p>Gerado em: ${new Date().toLocaleString('pt-BR')}</p></div><div class="result-heading"><div><h2>Escala do turno</h2><div class="result-meta">${badge(statusText(),statusText()==='Pronta'?'green':'amber')}<span>${dateLabel(result.config.date)}</span><span>${S.duration(result.workMinutes)} efetivas</span></div></div><div class="actions"><button class="button small" data-action="csv">${icon('download')} Baixar CSV</button><button class="button small" data-action="print">${icon('download')} Gerar PDF</button><button class="button small" data-action="save-draft">Salvar rascunho</button><button class="button primary" data-action="confirm-schedule" ${result.complete&&result.organizers?.length?'':'disabled'}>Confirmar escala</button></div></div>
 ${result.warnings.length?alertBox(result.warnings.map(esc).join('<br>')):result.gaps.length?alertBox('Não foi encontrada uma distribuição completa com estas regras. Revise a equipe e as fixações.'):alertBox('A simulação cobriu todos os postos respeitando as restrições cadastradas. Revise os dados com a liderança antes de qualquer uso operacional.','success')}
 <div class="card organizer-result"><strong>Organização da linha:</strong> ${organizerNames.length?organizerNames.map(esc).join(', '):'Nenhum assistente selecionado'}</div>
 <div class="card"><div class="table-scroll" tabindex="0" aria-label="Escala por horário e posto"><table class="schedule-table"><thead><tr><th>HORÁRIO</th>${result.positions.map(s=>`<th>${s.id} · ${s.name}${s.slot>1?' · '+s.slot:''}</th>`).join('')}${extraPosts.map(s=>`<th>${esc(s.id)} · ${esc(s.name)}${s.slot>1?' · '+s.slot:''}<small>Adicional</small></th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div><div class="export-note">Os horários consideram minutos efetivamente trabalhados. Azul marca mudança de pessoa. Os postos adicionais são manuais e não seguem o rodízio 20–70. Pausas não contam como saída do posto.</div></div>
 ${result.gaps.length?`<div class="card wide-card"><div class="card-head"><h3>Cobertura que precisa de revisão</h3>${badge(`${result.gaps.length} períodos`,'amber')}</div><ul class="alerts-list">${result.gaps.map(g=>`<li><strong>${S.clock(g.start)} — ${S.clock(g.end)} · ${esc(result.positions.find(s=>s.key===g.station)?.name||extraPosts.find(s=>s.key===g.station)?.name||g.station)}</strong><br>Sem pessoa atribuída. Adicione suplentes ou revise fixações e presenças; a restrição não foi flexibilizada.</li>`).join('')}</ul></div>`:''}</section>`;
}
function employeePage(){
 const filtered=employees.filter(p=>`${p.name} ${p.sector||''} ${p.role||'Operador'}`.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));
 $('#app').innerHTML=heading('PESSOAS E RESTRIÇÕES','Funcionários','Cadastre operadores e assistentes, setor e disponibilidade.',`<button class="button primary" data-action="new-employee">${icon('plus')} Novo funcionário</button>`)+alertBox('Operadores ativos podem ocupar postos permitidos. Assistentes ativos podem ser selecionados para organizar a linha na montagem. A restrição “sem cola” limita o operador ao clampe (30) neste protótipo.','info')+
 `<div class="employee-toolbar"><input id="employeeSearch" type="search" placeholder="Buscar nome, setor ou categoria…" aria-label="Buscar funcionário" value="${esc(query)}"><div class="actions">${badge(`${selected().length} operadores ativos`,'green')}${badge(`${assistants().length} assistentes ativos`,'green')}${badge(`${employees.filter(p=>!p.present).length} ausentes`,'gray')}</div></div><div class="card"><div class="table-scroll" tabindex="0" aria-label="Lista de funcionários"><table style="min-width:900px"><thead><tr><th>FUNCIONÁRIO / MATRÍCULA</th><th>CATEGORIA</th><th>SETOR</th><th>REGRA DE POSTO</th><th>PERMISSÕES</th><th>DISPONIBILIDADE</th><th>AÇÃO</th></tr></thead><tbody>${filtered.map(p=>`<tr><td><div class="table-person">${avatar(p.name)}<div><strong>${esc(p.name)}</strong><small>${esc(p.registration||'')}</small></div></div></td><td>${badge(p.role||'Operador',(p.role||'Operador')==='Assistente'?'amber':'green')}</td><td>${badge(p.sector||'Não informado',p.sector==='Subconjunto'?'green':'gray')}</td><td>${p.role==='Assistente'?'<span class="helper">Organização</span>':p.fixed?badge('Fixo · '+S.stations.find(s=>s.id===p.fixed)?.name):badge('Rodízio','gray')}</td><td>${p.role==='Assistente'?'<span class="helper">Fora dos postos</span>':p.noGlue?badge('Sem cola · clampe','amber'):`<span class="helper">${p.allowed.length} postos permitidos</span>`}</td><td><button class="availability-toggle ${p.present?'is-active':''}" data-toggle-presence="${esc(p.id)}" aria-pressed="${p.present}" aria-label="${p.present?'Marcar '+esc(p.name)+' como ausente':'Marcar '+esc(p.name)+' como ativo na linha'}"><span></span>${p.present?'Ativo na linha':'Ausente'}</button></td><td><button class="button small" data-edit="${esc(p.id)}" aria-label="Editar ${esc(p.name)}">Editar</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">Nenhum funcionário cadastrado. Clique em Novo funcionário para começar.</td></tr>'}</tbody></table></div></div><p class="helper">Ativo na linha = disponível para a função da sua categoria. Ausente = fica fora da escala e da organização.</p>`;
 $('#employeeSearch').addEventListener('input',e=>{query=e.target.value;const pos=e.target.selectionStart;employeePage();$('#employeeSearch').focus();try{$('#employeeSearch').setSelectionRange(pos,pos);}catch{}});
}
function editEmployee(id){
 const existing=employees.find(p=>p.id===id),p=existing||{id:'',name:'',sector:'Subconjunto',role:'Operador',active:true,present:false,noGlue:false,allowed:S.stations.map(s=>s.id),fixed:'',initial:'',supportPreckoff:false,supportNeedle:false};
 const dialog=$('#employeeDialog');dialog.innerHTML=`<form id="employeeForm"><div class="dialog-head"><h2 id="employeeTitle">${existing?'Editar':'Novo'} funcionário</h2><button type="button" class="icon-button" data-close="employeeDialog" aria-label="Fechar">×</button></div><div class="dialog-body"><label class="field">Nome completo<input name="name" required maxlength="100" value="${esc(p.name)}" placeholder="Nome completo"></label><label class="field">Matrícula<input name="registration" maxlength="40" value="${esc(p.registration||'')}" placeholder="Identificação interna"></label><div class="form-grid two"><label class="field">Categoria<select name="role" required>${options([{value:'Operador',label:'Operador'},{value:'Assistente',label:'Assistente'}],p.role||'Operador')}</select></label><label class="field">Setor<select name="sector" required>${options(sectors().map(x=>({value:x,label:x})),p.sector||'Subconjunto')}</select></label></div><div id="operatorFields"><label class="check-field"><input name="noGlue" type="checkbox" ${p.noGlue?'checked':''}>Restrição: não pode trabalhar com cola</label><p class="helper">No cenário demonstrativo, esta restrição limita a alocação ao clampe (30).</p><label class="field">Posto fixo<select name="fixed">${options([{value:'',label:'Sem fixação · participa do rodízio'},...S.stations.map(s=>({value:s.id,label:s.id+' · '+s.name}))],p.fixed)}</select></label><label class="field">Preferência na distribuição inicial<select name="initial">${options([{value:'',label:'Distribuir automaticamente'},...S.stations.map(s=>({value:s.id,label:s.id+' · '+s.name}))],p.initial)}</select></label><p class="helper">Postos permitidos no exemplo</p><div class="allowed-list">${S.stations.map(s=>`<label><input type="checkbox" name="allowed" value="${s.id}" ${p.allowed.includes(s.id)?'checked':''}>${s.name}</label>`).join('')}</div><label class="field">Restrições por posto (marque os processos bloqueados)<div class="allowed-list">${S.stations.map(s=>`<label><input type="checkbox" name="restricted" value="${s.id}" ${(p.restrictions||[]).some(r=>r.stationId===s.id)?'checked':''}>${s.id} · ${s.name}</label>`).join('')}</div></label><label class="field">Motivo da restrição<input name="restrictionReason" maxlength="200" value="${esc(p.restrictions?.[0]?.reason||'')}" placeholder="Ex.: restrição temporária"></label><label class="field">Restrição até (opcional)<input type="date" name="restrictionUntil" value="${esc(p.restrictions?.[0]?.expiresOn||'')}"></label><p class="helper">Apoio quando sobra na equipe</p><label class="check-field"><input name="supportPreckoff" type="checkbox" ${p.supportPreckoff?'checked':''}>Pode fazer acúmulo de preckoff</label><label class="check-field"><input name="supportNeedle" type="checkbox" ${p.supportNeedle?'checked':''}>Pode fazer acúmulo de agulha</label></div><label class="field">Observações<textarea name="notes" maxlength="500" rows="2">${esc(p.notes||'')}</textarea></label><label class="check-field"><input type="checkbox" name="present" ${p.present?'checked':''}>Ativo na linha · disponível para a função da categoria</label><p class="error-text" id="employeeError" role="alert"></p></div><div class="dialog-foot"><button type="button" class="button" data-close="employeeDialog">Cancelar</button><button class="button primary" type="submit">Salvar funcionário</button></div></form>`;
 const restriction=dialog.querySelector('[name=noGlue]'),role=dialog.querySelector('[name=role]');
 function syncRestriction(){dialog.querySelectorAll('[name=allowed]').forEach(c=>{if(restriction.checked)c.checked=c.value==='30';c.disabled=restriction.checked;});const fixed=dialog.querySelector('[name=fixed]');for(const o of fixed.options)o.disabled=restriction.checked&&!!o.value&&o.value!=='30';if(restriction.checked&&fixed.value&&fixed.value!=='30')fixed.value='30';}
 function syncRole(){dialog.querySelector('#operatorFields').hidden=role.value==='Assistente';}
 restriction.addEventListener('change',syncRestriction);role.addEventListener('change',syncRole);syncRestriction();syncRole();
 $('#employeeForm').addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.currentTarget),assistant=form.get('role')==='Assistente',noGlue=!assistant&&form.has('noGlue'),allowed=assistant?S.stations.map(s=>s.id):noGlue?['30']:form.getAll('allowed'),fixed=assistant?'':form.get('fixed'),name=String(form.get('name')).trim();let error='';if(!name)error='Informe o nome do funcionário.';else if(!sectors().includes(form.get('sector')))error='Selecione um setor válido.';else if(!['Operador','Assistente'].includes(form.get('role')))error='Selecione uma categoria válida.';else if(!allowed.length)error='Selecione pelo menos um posto permitido.';else if(fixed&&!allowed.includes(fixed))error='O posto fixo deve estar entre os postos permitidos.';else if(!existing&&employees.length>=30)error='Limite de 30 cadastros neste protótipo.';else if(employees.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))error='Já existe um cadastro com este nome.';if(error){$('#employeeError').textContent=error;return;}
 const initial=!assistant&&allowed.includes(String(form.get('initial')))?String(form.get('initial')):'';const restricted=assistant?[]:form.getAll('restricted');if(restricted.length&&!String(form.get('restrictionReason')).trim()){$('#employeeError').textContent='Informe o motivo da restrição.';return;}const restrictions=restricted.map(stationId=>({stationId,reason:String(form.get('restrictionReason')).trim(),expiresOn:String(form.get('restrictionUntil')||'')}));
 const updated={...p,id:existing?.id||crypto.randomUUID(),name,registration:String(form.get('registration')).trim(),notes:String(form.get('notes')).trim(),restrictions,sector:String(form.get('sector')),role:String(form.get('role')),allowed,fixed,initial,noGlue,active:true,present:form.has('present'),supportPreckoff:!assistant&&form.has('supportPreckoff'),supportNeedle:!assistant&&form.has('supportNeedle')};
 if(existing)employees=employees.map(x=>x.id===id?updated:x);else employees.push(updated);reconcileAssignments();invalidate();dialog.close();render();notify('Funcionário salvo. Gere a escala novamente para aplicar as alterações.');});
 dialog.showModal();
}
function fpStations(p){return Array.isArray(p?.stations)&&p.stations.length?p.stations:S.stations.map(s=>({id:s.id,name:s.name,requiredCount:1,notes:''}));}
function fpPage(){
 const p=catalog().find(x=>x.id===fpFocus)||product(),hasAny=catalog().length>0,used=new Set((config.history||[]).map(s=>s.fpId));
 $('#app').innerHTML=heading('FOLHAS DE ESPECIFICAÇÃO','FPs','Defina os processos e a equipe necessária para cada produto.',`<button class="button primary" data-action="new-fp">${icon('plus')} Nova FP</button>`)+`<div class="fp-layout"><aside class="card fp-list">${catalog().map(x=>`<button class="product-button ${x.id===p.id?'active':''}" data-product="${esc(x.id)}"><strong>${esc(x.name)}</strong><small>${esc(x.fp)} · Rev. ${esc(x.revision)}</small>${badge(x.status||'Ativa',x.status==='Arquivada'?'gray':'green')}</button>`).join('')||'<div class="empty-state">Nenhuma FP cadastrada.<br>Cadastre a primeira FP para montar uma escala.</div>'}</aside><article class="card fp-body">${hasAny?`<div class="card-head"><div><p class="eyebrow">FOLHA DE ESPECIFICAÇÃO</p><h2>${esc(p.fp)}</h2></div>${badge(p.status||'Ativa',p.status==='Arquivada'?'gray':'green')}</div><h3>${esc(p.name)}</h3><p>${esc(p.variation)}</p><dl class="spec-grid"><div><dt>DESTINO</dt><dd>${esc(p.market)}</dd></div><div><dt>REVISÃO</dt><dd>${esc(p.revision)}</dd></div><div><dt>PRODUTO</dt><dd>${esc(p.product||p.name)}</dd></div><div><dt>OPERADORES NECESSÁRIOS</dt><dd>${fpStations(p).reduce((n,s)=>n+Number(s.requiredCount||1),0)}</dd></div></dl><h3>Postos desta FP</h3><div class="route-flow">${fpStations(p).map(s=>`<span>${esc(s.id)} · ${esc(s.name)} · ${Number(s.requiredCount||1)} pessoa(s)</span>`).join('')}</div><p class="helper">${esc(p.notes||'Use somente informações conferidas com a FP aprovada.')}</p><div class="actions"><button class="button primary" data-use-product="${esc(p.id)}" ${p.status==='Arquivada'?'disabled':''}>Montar escala desta FP ${icon('arrow')}</button><button class="button" data-edit-fp="${esc(p.id)}">Editar</button><button class="button" data-duplicate-fp="${esc(p.id)}">Duplicar</button><button class="button" data-archive-fp="${esc(p.id)}">${p.status==='Arquivada'?'Reativar':'Arquivar'}</button><button class="button danger" data-delete-fp="${esc(p.id)}" ${used.has(p.id)?'disabled title="FP usada em escala; arquive para preservar o histórico"':''}>Excluir</button></div>`:'<div class="empty-state">Nenhuma FP cadastrada.<br>Cadastre uma FP para começar.</div>'}</article></div>`;
}
function editFP(id,duplicate=false){
 const original=catalog().find(x=>x.id===id),p=duplicate?null:original,d=$('#fpDialog'),positions=fpStations(original);
 d.innerHTML=`<form id="fpForm"><div class="dialog-head"><h2 id="fpDialogTitle">${duplicate?'Duplicar FP':p?'Editar FP':'Nova FP'}</h2><button type="button" class="icon-button" data-close="fpDialog" aria-label="Fechar">×</button></div><div class="dialog-body"><label class="field">Código da FP<input name="fp" required maxlength="120" value="${esc(duplicate?'':p?.fp||'')}" placeholder="Ex.: FP 001"></label><label class="field">Nome<input name="name" required maxlength="120" value="${esc(original?.name||'')}" placeholder="Ex.: Bolsa nacional"></label><div class="form-grid two"><label class="field">Destino<select name="market">${options(['Nacional','Internacional'].map(x=>({value:x,label:x})),original?.market||'Nacional')}</select></label><label class="field">Revisão<input name="revision" required maxlength="30" value="${esc(original?.revision||'')}" placeholder="Ex.: 01"></label></div><label class="field">Tipo / variação<input name="variation" required maxlength="120" value="${esc(original?.variation||'')}"></label><label class="field">Produto<input name="product" required maxlength="120" value="${esc(original?.product||original?.name||'')}"></label><h3>Postos necessários</h3><p class="helper">Marque os postos desta FP e informe a quantidade de operadores por posto (máximo de 12 posições no total).</p><div class="fp-station-list">${S.stations.map(s=>{const current=positions.find(x=>x.id===s.id);return `<div class="fp-station-row"><label class="check-field"><input type="checkbox" name="station-${s.id}" ${current?'checked':''}>${s.id} · ${s.name}</label><label class="field">Pessoas<input type="number" name="count-${s.id}" min="1" max="4" value="${Number(current?.requiredCount||1)}"></label></div>`;}).join('')}</div><label class="field">Observações<textarea name="notes" maxlength="500" rows="2">${esc(original?.notes||'')}</textarea></label><p class="error-text" id="fpError" role="alert"></p></div><div class="dialog-foot"><button type="button" class="button" data-close="fpDialog">Cancelar</button><button type="submit" class="button primary">Salvar FP</button></div></form>`;
 d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),stations=S.stations.filter(s=>f.has('station-'+s.id)).map(s=>({id:s.id,name:s.name,requiredCount:Number(f.get('count-'+s.id)),notes:''}));const item={id:p?.id||crypto.randomUUID(),name:String(f.get('name')).trim(),market:String(f.get('market')),variation:String(f.get('variation')).trim(),fp:String(f.get('fp')).trim(),revision:String(f.get('revision')).trim(),product:String(f.get('product')).trim(),notes:String(f.get('notes')).trim(),status:p?.status||'Ativa',stations};if(!item.name||!item.fp||!item.variation||!item.product||!item.revision||!stations.length||stations.some(s=>!Number.isInteger(s.requiredCount)||s.requiredCount<1||s.requiredCount>4)||stations.reduce((n,s)=>n+s.requiredCount,0)>12){$('#fpError').textContent='Preencha os dados e selecione de 1 a 12 posições válidas.';return;}if(catalog().length>=50&&!p){$('#fpError').textContent='Limite de 50 FPs.';return;}if(catalog().some(x=>x.id!==item.id&&x.fp.toLocaleLowerCase('pt-BR')===item.fp.toLocaleLowerCase('pt-BR'))){$('#fpError').textContent='Este código de FP já existe.';return;}config.fps=p?catalog().map(x=>x.id===p.id?item:x):[...catalog(),item];if(!p||!activeCatalog().some(x=>x.id===config.product))config.product=item.id;fpFocus=item.id;invalidate();d.close();fpPage();notify('FP salva no catálogo.');});d.showModal();
}
function editExtra(){
 const d=$('#extraDialog');d.innerHTML=`<form id="extraForm"><div class="dialog-head"><h2 id="extraDialogTitle">Adicionar outro posto</h2><button type="button" class="icon-button" data-close="extraDialog" aria-label="Fechar">×</button></div><div class="dialog-body"><label class="field">Número do posto<input name="id" required inputmode="numeric" pattern="[0-9]{1,3}" maxlength="3" placeholder="Ex.: 80"></label><label class="field">Nome do processo<input name="name" required maxlength="60" placeholder="Ex.: Apoio de embalagem"></label><label class="field">Quantidade de pessoas<input name="requiredCount" type="number" min="1" max="4" value="1" required></label><label class="field">Observação<input name="notes" maxlength="200" placeholder="Opcional"></label><p class="helper">Depois de adicionar, escolha um operador ativo na montagem da escala.</p><p class="error-text" id="extraError" role="alert"></p></div><div class="dialog-foot"><button type="button" class="button" data-close="extraDialog">Cancelar</button><button type="submit" class="button primary">Adicionar posto</button></div></form>`;
 d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),id=String(f.get('id')).trim(),name=String(f.get('name')).trim(),requiredCount=Number(f.get('requiredCount')),notes=String(f.get('notes')).trim();if(extras().length>=8||extraSlots().length+requiredCount>12){$('#extraError').textContent='Limite de 8 postos ou 12 posições adicionais.';return;}if(!/^\d{1,3}$/.test(id)||S.stations.some(s=>s.id===id)||extras().some(s=>s.id===id)||!name||!Number.isInteger(requiredCount)||requiredCount<1||requiredCount>4){$('#extraError').textContent='Informe número e nome válidos; o número não pode se repetir.';return;}config.extraPosts=[...extras(),{id,name,requiredCount,notes,employeeIds:[],employeeId:''}];invalidate();d.close();schedule();notify(`Posto ${id} adicionado. Escolha um operador para ele.`);});d.showModal();
}
function confirmChange(title,description,word,action){const d=$('#confirmDialog');d.innerHTML=`<form id="confirmForm"><div class="dialog-head"><h2 id="confirmDialogTitle">${esc(title)}</h2><button type="button" class="icon-button" data-close="confirmDialog" aria-label="Fechar">×</button></div><div class="dialog-body"><p>${esc(description)}</p><label class="field">Digite ${esc(word)} para confirmar<input name="confirmation" required autocomplete="off" aria-label="Palavra de confirmação"></label><p class="error-text" id="confirmError" role="alert"></p></div><div class="dialog-foot"><button type="button" class="button" data-close="confirmDialog">Cancelar</button><button type="submit" class="button danger" disabled>Confirmar</button></div></form>`;d.querySelector('[name=confirmation]').addEventListener('input',e=>{d.querySelector('[type=submit]').disabled=e.target.value!==word;});d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();if(new FormData(e.currentTarget).get('confirmation')!==word){$('#confirmError').textContent=`Digite ${word} exatamente.`;return;}d.close();action();});d.showModal();}
function historyPage(){
 const entries=[...(config.history||[])].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
 $('#app').innerHTML=heading('RASTREABILIDADE','Histórico de escalas','Consulte as escalas confirmadas e seus registros de planejamento.',linkButton('schedule','Montar escala',true,'plus'))+`<div class="card history-filters"><label class="field">Período<input type="month" id="historyMonth"></label><label class="field">FP<input id="historyFP" type="search" placeholder="Código"></label><label class="field">Produto<input id="historyProduct" type="search" placeholder="Produto"></label><label class="field">Turno<input id="historyShift" type="search" placeholder="Turno"></label><label class="field">Funcionário<input id="historyPerson" type="search" placeholder="Nome"></label><label class="field">Assistente<input id="historyAssistant" type="search" placeholder="Nome"></label></div><div id="historyList"></div>`;
 const draw=()=>{const month=$('#historyMonth').value,fp=$('#historyFP').value.toLocaleLowerCase('pt-BR'),productQuery=$('#historyProduct').value.toLocaleLowerCase('pt-BR'),assistantQuery=$('#historyAssistant').value.toLocaleLowerCase('pt-BR'),shift=$('#historyShift').value.toLocaleLowerCase('pt-BR'),person=$('#historyPerson').value.toLocaleLowerCase('pt-BR');const matches=entries.filter(x=>(!month||x.date.startsWith(month))&&(!fp||x.fp.toLocaleLowerCase('pt-BR').includes(fp))&&(!productQuery||x.product.toLocaleLowerCase('pt-BR').includes(productQuery))&&(!assistantQuery||x.organizers.join(' ').toLocaleLowerCase('pt-BR').includes(assistantQuery))&&(!shift||x.shift.toLocaleLowerCase('pt-BR').includes(shift))&&(!person||x.names.toLocaleLowerCase('pt-BR').includes(person)));$('#historyList').innerHTML=matches.length?matches.map(x=>`<article class="card history-item"><div><strong>${dateLabel(x.date)} · ${esc(x.shift)}</strong><p>${esc(x.fp)} · ${esc(x.product)}</p><small>${esc(x.organizers.join(', ')||'Sem assistente')} · ${esc(x.positions)} posições · ${esc(x.status)}</small></div><button class="button" data-history="${esc(x.id)}">Detalhes</button></article>`).join(''):`<div class="card empty-state">${entries.length?'Nenhuma escala corresponde aos filtros.':'Nenhuma escala confirmada. Monte e confirme a primeira escala.'}</div>`;};
 $('#app').querySelectorAll('.history-filters input').forEach(x=>x.addEventListener('input',draw));draw();
}
function historyDetails(id){const item=(config.history||[]).find(x=>x.id===id);if(!item)return;const d=$('#stationDialog'),snap=item.snapshot;d.innerHTML=`<div class="dialog-head"><h2 id="stationTitle">${esc(item.fp)} · ${dateLabel(item.date)}</h2><button class="icon-button" data-close="stationDialog" aria-label="Fechar">×</button></div><div class="dialog-body"><p><strong>Produto:</strong> ${esc(item.product)} · <strong>Turno:</strong> ${esc(item.shift)}</p><p><strong>Assistentes:</strong> ${esc(item.organizers.join(', ')||'Nenhum')}</p><p><strong>Status:</strong> ${esc(item.status)} · <strong>Criada:</strong> ${new Date(item.createdAt).toLocaleString('pt-BR')} · <strong>Alterada:</strong> ${new Date(item.updatedAt).toLocaleString('pt-BR')}</p><div class="table-scroll"><table class="schedule-table"><thead><tr><th>Horário</th>${[...snap.positions,...(snap.extraPosts||[])].map(s=>`<th>${esc(s.id)} · ${esc(s.name)}${s.slot>1?' · '+s.slot:''}</th>`).join('')}</tr></thead><tbody>${snap.rows.filter(r=>r.kind==='work').map(r=>`<tr><td>${S.clock(r.start)}–${S.clock(r.end)}</td>${[...r.assign,...(snap.extraPosts||[]).map(p=>p.employeeId)].map(id=>`<td>${esc(snap.employees.find(p=>p.id===id)?.name||'Pendente')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="helper">${esc(item.notes||'Sem observações.')}</p></div><div class="dialog-foot"><button class="button" data-close="stationDialog">Fechar</button>${item.status==='Pronta'?`<button class="button primary" data-history-status="${esc(item.id)}:Finalizada">Finalizar</button><button class="button danger" data-history-status="${esc(item.id)}:Cancelada">Cancelar</button>`:''}<button class="button primary" data-action="history-print">Gerar PDF</button></div>`;d.showModal();
}
async function saveSchedule(finalize=false){
 if(!result||!result.rows?.length||(finalize&&!result.complete)||storageMode==='local'){notify(storageMode==='local'?'Banco SQL indisponível. Não confirme uma escala local.':'Resolva as pendências antes de confirmar.');return;}
 if((config.history||[]).length>=100){notify('Limite de registros nesta versão. Exporte e revise a retenção do histórico.');return;}
 if(!config.date||!config.shiftName||(finalize&&!result.organizers?.length)||!catalog().some(p=>p.id===config.product)){notify('Informe data, turno, FP e assistente responsável.');return;}
 const p=product(),now=new Date().toISOString(),snapshot=structuredClone(result),id=crypto.randomUUID();
 const entry={id,date:config.date,shift:config.shiftName,fpId:p.id,fp:p.fp,product:p.product||p.name,organizers:(result.organizers||[]).map(x=>x.name),positions:result.positions.length,status:finalize?'Pronta':result.complete?'Rascunho':'Incompleta',names:result.employees.filter(x=>result.people.includes(x.id)).map(x=>x.name).join(' '),notes:config.scheduleNotes||'',snapshot,createdAt:now,updatedAt:now};
 config.history=[...(config.history||[]),entry];if(finalize)config.confirmedId=id;
 try{await commit();notify(finalize?'Escala confirmada e salva no histórico.':'Rascunho salvo no histórico.');location.hash='history';}
 catch(error){config.history=config.history.filter(x=>x.id!==id);delete config.confirmedId;storageStatus('Falha ao salvar no banco SQL.');notify(`Escala não salva: ${error.message}`);}
}
async function updateHistoryStatus(id,status){const item=(config.history||[]).find(x=>x.id===id);if(!item||item.status!=='Pronta'||!['Finalizada','Cancelada'].includes(status))return;const previous=item.updatedAt;item.status=status;item.updatedAt=new Date().toISOString();try{await commit();$('#stationDialog').close();historyPage();notify('Status da escala atualizado.');}catch(error){item.status='Pronta';item.updatedAt=previous;notify(`Não foi possível atualizar: ${error.message}`);}}
function settingsPage(){
 const used=new Set(employees.map(x=>x.sector)),shifts=config.shifts||[];
 $('#app').innerHTML=heading('ADMINISTRAÇÃO','Configurações','Parâmetros de produção e ações de manutenção.')+`<div class="settings-grid"><section class="card settings-card"><h2>Setores</h2><p>Setores disponíveis no cadastro de funcionários.</p><div class="settings-list">${sectors().map(x=>`<div><span>${esc(x)}</span><button class="button small" data-remove-sector="${esc(x)}" ${used.has(x)?'disabled title="Há funcionários neste setor"':''}>Remover</button></div>`).join('')}</div><form id="sectorForm" class="form-grid two"><label class="field">Novo setor<input name="sector" maxlength="60" required placeholder="Nome do setor"></label><button class="button primary">Adicionar setor</button></form></section>
 <section class="card settings-card"><h2>Turnos</h2><p>Horários usados na montagem da escala.</p><div class="settings-list">${shifts.map(x=>`<div><span>${esc(x.name)} · ${esc(x.start)}–${esc(x.end)}</span><button class="button small" data-remove-shift="${esc(x.id)}" ${x.name===config.shiftName?'disabled title="Turno em uso"':''}>Remover</button></div>`).join('')}</div><form id="shiftForm"><label class="field">Nome<input name="name" maxlength="40" required placeholder="Ex.: Turno B"></label><div class="form-grid two"><label class="field">Início<input name="start" type="time" required></label><label class="field">Fim<input name="end" type="time" required></label></div><button class="button primary">Adicionar turno</button></form></section>
 <section class="card settings-card"><h2>Dados</h2><p>As ações de limpeza exigem confirmação digitada.</p><div class="actions"><button class="button danger" data-action="clear-schedules">Limpar escalas (${(config.history||[]).length})</button><button class="button danger" data-action="clear-employees" ${employees.length?'':'disabled'}>Limpar funcionários (${employees.length})</button><button class="button danger" data-action="clear-unused-fps" ${catalog().some(x=>!(config.history||[]).some(h=>h.fpId===x.id))?'':'disabled'}>Limpar FPs não utilizadas</button><button class="button" data-action="reset-settings">Restaurar configuração inicial</button></div></section></div><p class="helper settings-note">Protótipo independente para avaliação interna. Não substitui procedimentos ou sistemas oficiais.</p>`;
 $('#sectorForm').addEventListener('submit',e=>{e.preventDefault();const name=String(new FormData(e.currentTarget).get('sector')).trim();if(!name||sectors().some(x=>x.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR'))){notify('Informe um setor novo.');return;}config.sectors=[...sectors(),name];save();settingsPage();notify('Setor adicionado.');});
 $('#shiftForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')).trim(),start=String(f.get('start')),end=String(f.get('end'));if(!name||!start||!end||S.minutes(end)<=S.minutes(start)||shifts.some(x=>x.name.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR'))){notify('Revise o nome e os horários do turno.');return;}config.shifts=[...shifts,{id:crypto.randomUUID(),name,start,end}];save();settingsPage();notify('Turno adicionado.');});
}
function exportCSV(){if(!result?.rows.length)return;const safe=v=>{let x=String(v??'');if(/^[=+@-]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"';};const posts=result.extraPosts||[];const lines=[['GESTOR DE SUBCONJUNTO — VERSÃO PILOTO'],[statusText()],['Data',result.config.date,'FP',catalog().find(p=>p.id===result.config.product)?.fp],['Organização da linha',...(result.organizers||[]).map(p=>p.name)],['Horário','Evento',...result.positions.map(s=>s.id+' '+s.name+(s.slot>1?' '+s.slot:'')),...posts.map(s=>s.id+' '+s.name+(s.slot>1?' '+s.slot:'')+' (adicional)')],...result.rows.map(r=>[S.clock(r.start)+' — '+S.clock(r.end),r.label,...r.assign.map(id=>r.kind==='break'?'Intervalo':nameOf(id,result.employees)),...posts.map(p=>r.kind==='break'?'Intervalo':p.employeeId?nameOf(p.employeeId,result.employees):'Pendente')]),['Pendências'],...result.warnings.map(x=>[x]),...result.gaps.map(g=>[`${g.station}: sem cobertura ${S.clock(g.start)} — ${S.clock(g.end)}`])];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.map(l=>l.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`escala-demonstrativa-${result.config.date}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function toggleMenu(open){$('#sidebar').classList.toggle('open',open);$('#navBackdrop').classList.toggle('open',open);$('#menuButton').setAttribute('aria-expanded',String(open));}
function render(){
 const route=location.hash.slice(1)||'overview';document.body.dataset.theme=theme;
 const page=pages.find(p=>p[0]===route)||pages[0];$('#breadcrumb').textContent=page[1];
 $('#nav').innerHTML=pages.map(([id,label,ico])=>`<a class="nav-link ${id===page[0]?'active':''}" href="#${id}" ${id===page[0]?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')+`<div class="nav-extras"><button class="nav-link" data-action="theme">${icon('moon')}Tema ${theme==='dark'?'claro':'escuro'}</button></div>`;
 ({overview,schedule,employees:employeePage,fp:fpPage,history:historyPage,settings:settingsPage}[page[0]])();toggleMenu(false);save();
}
document.addEventListener('click',e=>{
 const button=e.target.closest('button,a');if(!button)return;
 if(button.dataset.close){$('#'+button.dataset.close).close();return;}
 if(button.dataset.togglePresence){const person=employees.find(item=>item.id===button.dataset.togglePresence);if(!person)return;person.present=!person.present;reconcileAssignments();invalidate();employeePage();notify(person.present?`${person.name} está disponível para sua função.`:`${person.name} foi marcado como ausente.`);return;}
 if(button.dataset.edit){editEmployee(button.dataset.edit);return;}
 if(button.dataset.editFp){editFP(button.dataset.editFp);return;}
 if(button.dataset.duplicateFp){editFP(button.dataset.duplicateFp,true);return;}
 if(button.dataset.archiveFp){const item=catalog().find(x=>x.id===button.dataset.archiveFp);if(item){item.status=item.status==='Arquivada'?'Ativa':'Arquivada';if(item.status==='Arquivada'&&config.product===item.id)config.product=activeCatalog()[0]?.id||'';invalidate();fpPage();notify(item.status==='Arquivada'?'FP arquivada.':'FP reativada.');}return;}
 if(button.dataset.deleteFp){const item=catalog().find(x=>x.id===button.dataset.deleteFp);if(!item||((config.history||[]).some(x=>x.fpId===item.id)))return;confirmChange('Apagar FP',`Apagar ${item.fp} (${item.name}) do catálogo? A ação não pode ser desfeita no sistema.`, 'APAGAR',()=>{config.fps=catalog().filter(x=>x.id!==item.id);if(config.product===item.id)config.product=catalog()[0]?.id||'';fpFocus=config.product;invalidate();fpPage();notify('FP apagada.');});return;}
 if(button.dataset.removeExtra){const post=extras().find(x=>x.id===button.dataset.removeExtra);if(!post)return;confirmChange('Remover posto',`Remover o posto adicional ${post.id} · ${post.name} deste turno?`,'REMOVER',()=>{config.extraPosts=extras().filter(x=>x.id!==post.id);invalidate();schedule();notify('Posto adicional removido.');});return;}
 if(button.dataset.removeSector){const name=button.dataset.removeSector;if(!employees.some(x=>x.sector===name)){config.sectors=sectors().filter(x=>x!==name);save();settingsPage();notify('Setor removido.');}return;}
 if(button.dataset.removeShift){const id=button.dataset.removeShift;config.shifts=(config.shifts||[]).filter(x=>x.id!==id||x.name===config.shiftName);save();settingsPage();notify('Turno removido.');return;}
 if(button.dataset.historyStatus){const [id,status]=button.dataset.historyStatus.split(':');updateHistoryStatus(id,status);return;}
 if(button.dataset.history){historyDetails(button.dataset.history);return;}
 if(button.dataset.product){fpFocus=button.dataset.product;fpPage();return;}
 if(button.dataset.useProduct){config.product=button.dataset.useProduct;config.manualAssignments={};config.locks={};invalidate();location.hash='schedule';return;}
 switch(button.dataset.action){case 'theme':theme=theme==='dark'?'light':'dark';save();render();break;case 'new-employee':editEmployee();break;case 'new-fp':editFP();break;case 'add-extra':editExtra();break;case 'clear-schedules':confirmChange('Limpar escalas','Remove permanentemente todas as escalas do histórico, a escala atual e postos adicionais. Funcionários e FPs permanecem.','LIMPAR ESCALAS',()=>{const {fps,sectors,shifts}=config;config={...S.defaults(),fps,sectors,shifts,history:[]};pendingOperation='clearSchedules';if(fps&&!fps.some(p=>p.id===config.product))config.product=fps[0]?.id||'';employees.forEach(p=>p.initial='');invalidate();render();notify('Escalas limpas.');});break;case 'clear-unused-fps':confirmChange('Limpar FPs não utilizadas','Exclui permanentemente as FPs sem escala registrada. FPs usadas em histórico serão preservadas.','LIMPAR',()=>{config.fps=catalog().filter(x=>(config.history||[]).some(h=>h.fpId===x.id));if(!config.fps.some(x=>x.id===config.product))config.product=activeCatalog()[0]?.id||'';invalidate();settingsPage();notify('FPs não utilizadas removidas.');});break;case 'reset-settings':confirmChange('Restaurar configuração inicial','Restaura setores e turnos padrão; mantém funcionários, FPs e histórico.','RESTAURAR',()=>{const defaults=S.defaults();config.sectors=[...new Set([...defaults.sectors,...employees.map(x=>x.sector)])];config.shifts=defaults.shifts;config.shiftName=defaults.shiftName;save();settingsPage();notify('Configuração inicial restaurada.');});break;case 'clear-employees':confirmChange('Limpar funcionários',`Apagar os ${employees.length} funcionários cadastrados e a escala atual? O histórico preserva os nomes já registrados.`,'APAGAR FUNCIONÁRIOS',()=>{employees=[];config.extraPosts=[];config.organizerIds=[];invalidate();render();notify('Funcionários e escala removidos.');});break;case 'confirm-schedule':saveSchedule(true);break;case 'save-draft':saveSchedule(false);break;case 'history-print':document.body.dataset.printMode='history';window.print();break;case 'csv':exportCSV();break;case 'print':document.body.dataset.printMode='all';window.print();break;case 'preckoff-print':document.body.dataset.printMode='preckoff';window.print();break;}
});
window.addEventListener('afterprint',()=>delete document.body.dataset.printMode);
$('#menuButton').addEventListener('click',()=>toggleMenu(!$('#sidebar').classList.contains('open')));$('#navBackdrop').addEventListener('click',()=>toggleMenu(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')toggleMenu(false);});
window.addEventListener('hashchange',()=>{viewIndex=0;render();window.scrollTo(0,0);});
setInterval(()=>{const clock=$('#pilotClock');if(clock){const now=new Date();clock.textContent=`${now.toLocaleDateString('pt-BR')} · ${now.toLocaleTimeString('pt-BR')}`;}},1000);
render();loadState();
